/* TEA-PTS: protótipo local. Dados iniciais extraídos das referências fornecidas. */
(function(root){'use strict';
const paths={overview:'index.html',signup:'cadastro.html',waiting:'aguardando-perfil.html',patients:'pacientes.html',createPatient:'criar-paciente.html',createPts:'criar-pts.html',patientHome:'inicio-paciente.html',proposals:'propostas-pts.html',pts:'pts.html',records:'prontuario.html',upload:'enviar-documento.html',timeline:'historico.html',profile:'meu-perfil.html'};
const titles={overview:'Todas as telas',signup:'Criar conta',waiting:'Aguardando perfil',patients:'Pacientes',createPatient:'Criar perfil de paciente',createPts:'Criar proposta de PTS',patientHome:'Meu cuidado',proposals:'Propostas de PTS',pts:'Programa Terapêutico Singular',records:'Prontuário',upload:'Enviar documento',timeline:'Histórico do PTS',profile:'Meu perfil'};
const professionals=[{id:'kaio-psi',name:'Kaio Felipe',specialty:'Psicólogo(a)'},{id:'kaio-med',name:'Kaio Felipe',specialty:'Médico(a)'},{id:'kaio-fisio',name:'Kaio Felipe',specialty:'Fisioterapeuta'},{id:'kaio2-psi',name:'Kaio Segunda Conta',specialty:'Psicólogo(a)'}];
const accounts=[{id:'priscila',name:'Priscila Martins'},{id:'pamella',name:'Pamella Rodrigues da Silva'},{id:'kaio2',name:'Kaio Segunda Conta'},{id:'kaio',name:'Kaio Felipe'}];
function initial(){return {version:3,createdPatients:[],patients:[{id:'maria',name:'Maria Sílvia Barreto Pessoa de Moraes',source:true},{id:'diego',name:'Diego Alves',source:true}],proposals:[{id:'proposta-referencia',patientId:'priscila',responsible:'kaio2-psi',team:[],social:'Situação inicial',status:'DRAFT'}],plans:{},contacts:{},activities:[],events:[],documents:[{id:'ref-silvia',patientId:'maria',title:'Silvia',description:'',created:'29/06/2026',updated:'03/07/2026',source:true},{id:'ref-cupcak',patientId:'maria',title:'Cupcakke devo',description:'',created:'28/06/2026',updated:'03/07/2026',source:true},{id:'ref-cupcak2',patientId:'maria',title:'CupcakKe 2',description:'',created:'28/06/2026',updated:'03/07/2026',source:true},{id:'ref-cupcak3',patientId:'maria',title:'CupcakKe',description:'',created:'28/06/2026',updated:'03/07/2026',source:true}]}}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glyphs={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m1 3a5 5 0 0 1 4 5v2"/>',plan:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v3H9zM9 11h6m-6 4h6"/>',folder:'<path d="M3 7V5h6l2 3h10v12H3Z"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l4 2"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',plus:'<path d="M12 4v16M4 12h16"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',file:'<path d="M5 3h9l5 5v13H5Z"/><path d="M14 3v6h5M8 13h8m-8 4h8"/>',logout:'<path d="M9 3H4v18h5M10 12h11m-4-4 4 4-4 4"/>',eye:'<path d="M2 12s4-6 10-6 10 6 10 6-4 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="2.5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m4 12 5 5L20 6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${glyphs[name]||glyphs.plan}</svg>`;
const brand=()=>'<a class="app-brand" href="index.html" data-od-id="brand"><img src="assets/teapts-marca.png" width="150" height="66" alt="Símbolo do TEA-PTS"><strong>TEA-PTS</strong></a>';
const avatar=(patient=false)=>`<span class="avatar ${patient?'avatar-patient':''}"><img src="assets/${patient?'avatar-paciente':'avatar-conta'}.png" width="${patient?42:33}" height="${patient?74:43}" alt="Avatar da referência fornecida"></span>`;
const initials=name=>`<span class="avatar initials" aria-hidden="true">${esc(name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join(''))}</span>`;
const person=(id,state)=>[...state.patients,...accounts].find(x=>x.id===id)||{id,name:state.newAccount?.name||'Paciente'};
const professional=id=>professionals.find(x=>x.id===id)||professionals[3];
const states={DRAFT:'Aguardando aprovação',PLANNING:'Em planejamento',RUNNING:'Em andamento',REJECTED:'Rejeitada',CONCLUDED:'Concluído',CANCELLED:'Cancelado',SUGGESTED:'Sugerida',ARCHIVED:'Arquivada'};
function link(screen,ctx,extra={}){const q=new URLSearchParams({role:ctx.role,patient:ctx.patient,...extra});return paths[screen]+'?'+q.toString()}
function action(label,id,primary=false,attrs=''){return `<button class="btn ${primary?'btn-primary':'btn-secondary'}" type="button" data-action="${id}" data-od-id="${id}" ${attrs}>${label}</button>`}
function buttonLink(label,screen,ctx,primary=false,extra={}){return `<a class="btn ${primary?'btn-primary':'btn-secondary'}" href="${link(screen,ctx,extra)}" data-od-id="go-${screen}">${label}</a>`}
const badge=t=>`<span class="badge badge-dot">${esc(t)}</span>`;
const empty=(title,desc,mark='folder',cta='',compact=false)=>`<div class="empty ${compact?'compact':''}" data-od-id="empty-state"><div class="empty-icon">${icon(mark)}</div><h2 data-od-id="empty-title">${title}</h2><p>${desc}</p>${cta}</div>`;
const notice=(s)=>`<div class="notice">${s}</div>`;
const field=(label,id,input,help='')=>`<div class="field"><label for="${id}">${label}</label>${input}${help?`<small id="${id}-help">${help}</small>`:''}</div>`;
const input=(id,placeholder,type='text',required=true,value='')=>`<input class="input" id="${id}" name="${id}" type="${type}" placeholder="${placeholder}" ${required?'required':''} value="${esc(value)}" data-od-id="${id}">`;
const option=(val,label,selected=false)=>`<option value="${esc(val)}" ${selected?'selected':''}>${esc(label)}</option>`;
function heading(title,description,eyebrow='',cta=''){return `<div class="heading"><div>${eyebrow?`<p class="eyebrow">${eyebrow}</p>`:''}<h1 data-od-id="page-title">${title}</h1><p>${description}</p></div>${cta}</div>`}
function banner(ctx,state){const p=person(ctx.patient,state),plan=state.plans[ctx.patient];return `<div class="person-banner" data-od-id="patient-banner">${p.source?avatar(true):initials(p.name)}<div><h2>${esc(p.name)}</h2><p>Programa Terapêutico Singular</p></div>${badge(plan?states[plan.status]:'Dados da referência')}</div>`}
function tabs(ctx,screen){return `<nav class="tabs" aria-label="Navegação do plano">${[['pts','Visão geral'],['records','Prontuário'],['timeline','Histórico']].map(([id,t])=>`<a href="${link(id,ctx)}" ${screen===id?'aria-current="page"':''} data-od-id="tab-${id}">${t}</a>`).join('')}</nav>`}
function user(ctx,state){return ctx.role==='patient'?{name:(ctx.patient==='new-account'?state.newAccount?.name:null)||'Priscila Martins',role:'Paciente',email:ctx.patient==='new-account'?(state.newAccount?.email||''):'',specialties:[]}:ctx.role==='admin'?{name:'Kaio Segunda Conta',role:'Administrador',specialties:['Administrador','Psicólogo(a)']}:{name:'Kaio Felipe',role:'Profissional',email:'',specialties:['Psicólogo(a)','Médico(a)','Fisioterapeuta']}}
function shell(screen,ctx,state,body){const u=user(ctx,state),isPatient=ctx.role==='patient';const nav=screen==='waiting'&&!state.createdPatients.includes(ctx.patient)?[['waiting','home','Início']]:isPatient?[['patientHome','home','Meu cuidado'],['proposals','plan','Propostas de PTS'],['pts','people','Meu PTS'],['records','folder','Prontuário'],['timeline','history','Histórico']]:[['patients','people','Pacientes'],['createPts','plan','Criar proposta de PTS'],...(ctx.role==='admin'?[['createPatient','plus','Criar perfil de paciente']]:[])];const group=['pts','records','timeline','upload'].includes(screen)?'Acompanhamento':'Área '+(isPatient?'do paciente':ctx.role==='admin'?'administrativa':'profissional');return `<div class="app"><aside class="sidebar" id="sidebar" data-od-id="sidebar">${brand()}<button class="icon-button menu-close" data-action="menu-close" aria-label="Fechar navegação">${icon('close')}</button><p class="nav-caption">${isPatient?'Meu cuidado':'Área de trabalho'}</p><nav aria-label="Menu principal">${nav.map(([key,i,title])=>`<a class="nav-link" href="${link(key,ctx)}" ${key===screen?'aria-current="page"':''} data-od-id="nav-${key}" aria-label="${title}" title="${title}">${icon(i)}<span class="nav-label">${title}</span></a>`).join('')}</nav><div class="side-bottom"><a class="nav-link" href="${link('profile',ctx)}" ${screen==='profile'?'aria-current="page"':''} data-od-id="nav-profile" aria-label="Meu perfil" title="Meu perfil">${icon('profile')}<span class="nav-label">Meu perfil</span></a><button class="nav-link" style="width:100%;border:0;background:transparent;text-align:left" data-action="logout" data-od-id="logout" aria-label="Sair da conta" title="Sair da conta">${icon('logout')}<span class="nav-label">Sair da conta</span></button><p class="side-note">Cuidado singular.<br>Construção compartilhada.</p></div></aside><div class="workspace"><header class="app-header" data-od-id="app-header"><button class="icon-button sidebar-toggle" data-action="sidebar-toggle" data-od-id="sidebar-toggle" aria-label="Recolher barra lateral" title="Recolher barra lateral" aria-controls="sidebar" aria-expanded="true">${icon('menu')}</button><button class="header-profile" data-action="profile" data-od-id="open-profile">${avatar()}<span><strong>${esc(u.name)}</strong><small>${u.role}</small></span>${icon('down')}</button></header><main class="content" id="content"><nav class="breadcrumb" aria-label="Caminho da página"><a href="${link(isPatient?'patientHome':'patients',ctx)}">Início</a><span aria-hidden="true">/</span><span>${titles[screen]}</span></nav><section class="section" data-od-id="screen-${screen}">${body}</section><footer class="page-footer"><span>TEA-PTS · Programa Terapêutico Singular</span><span>Dados de demonstração · sem conexão ao servidor</span></footer></main></div></div>${dialogs()}`}
function dialogs(){return '<dialog id="modal" aria-labelledby="modal-title" data-od-id="modal"><button class="icon-button close" data-action="close" aria-label="Fechar janela">'+icon('close')+'</button><div id="modal-body"></div></dialog><div id="toast" class="toast" role="status" aria-live="polite"></div>'}
function overview(){const groups=[['Acesso e perfis',[['teapts-login.html','Login','Entrada com e-mail e senha e recuperação de acesso.'],['cadastro.html','Cadastro','Nome, e-mail, senha e confirmação de senha.'],['aguardando-perfil.html','Aguardando perfil','Estado inicial da conta de Priscila Martins.'],['meu-perfil.html?role=professional','Perfil profissional','Kaio Felipe e suas especialidades.'],['meu-perfil.html?role=patient','Perfil do paciente','Priscila Martins e opções da conta.'],['meu-perfil.html?role=admin','Perfil administrativo','Kaio Segunda Conta e suas permissões.']]],['Área profissional e administrativa',[['pacientes.html','Pacientes','Lista, busca e acesso ao PTS de cada paciente.'],['criar-paciente.html','Criar perfil de paciente','Seleção de conta e contatos de suporte opcionais.'],['criar-pts.html','Criar proposta de PTS','Paciente, equipe multidisciplinar e situação social.']]],['Jornada do paciente',[['inicio-paciente.html','Meu cuidado','Estado sem PTS ativo e acesso às propostas.'],['propostas-pts.html','Propostas de PTS','Consulta, escolha de equipe e confirmação de aprovação.'],['pts.html?role=patient&patient=priscila&scenario=approved','PTS em planejamento','Visão do paciente com atividades e equipe expansíveis.'],['historico.html?role=patient&patient=priscila','Histórico','Estado vazio e eventos gerados pelas ações do protótipo.']]],['Prontuário e documentos',[['prontuario.html?role=professional&patient=maria','Prontuário com documentos','Metadados visíveis nas referências fornecidas.'],['prontuario.html?role=patient&patient=priscila','Prontuário vazio','Estado sem documentos para o paciente.'],['enviar-documento.html?role=professional&patient=maria','Enviar documento','Título, descrição e seleção de arquivo local.']]]];let n=0;return `<main class="overview"><header>${brand()}<span class="meta">PROTÓTIPO WEB · REFERÊNCIAS MOBILE</span></header>${heading('Um cuidado. Todas as conexões.','Explore as telas web do TEA-PTS, adaptadas das imagens e do documento de requisitos.','Visão geral do protótipo',`<a class="btn btn-primary" href="pacientes.html">Explorar área profissional ${icon('arrow')}</a>`)}${groups.map(([title,items])=>`<section class="section" data-od-id="overview-group-${++n}"><h2 class="group-title">${title}</h2>${items.map(([href,title,desc],i)=>`<article class="log-row" data-od-id="screen-link-${n}-${i}"><span class="meta">${String(i+1).padStart(2,'0')}</span><div><h3>${title}</h3><p>${desc}</p></div><a class="btn btn-ghost" href="${href}" aria-label="Abrir ${title}">Abrir tela ${icon('arrow')}</a></article>`).join('')}</section>`).join('')}<p class="review-note">Os nomes e avatares vêm das imagens fornecidas. A aprovação do PTS, os cadastros e os arquivos enviados funcionam apenas neste protótipo. Os documentos das referências têm metadados, mas seus arquivos originais não foram fornecidos.<br><a class="link" href="figma-teapts.zip">Baixar pacote editável para Figma ${icon('arrow')}</a> · <a class="link" href="LEIA-ME-TEAPTS.md">Orientações de uso</a></p></main>`}
function signup(){return `<main class="signup-layout"><section class="signup-story" data-od-id="signup-presentation">${brand()}<div><p class="eyebrow" style="color:var(--muted)">Um novo começo no cuidado</p><h1>Seu cuidado começa com uma conexão.</h1><p>Crie sua conta para participar da construção do seu Programa Terapêutico Singular.</p></div><p class="small">Pacientes e profissionais.<br>Uma visão compartilhada do cuidado.</p></section><section class="signup-form" data-od-id="signup-form-section"><a class="link" href="teapts-login.html">${icon('back')}Voltar ao login</a><h2 style="margin-top:24px" data-od-id="signup-title">Crie sua conta</h2><p>Preencha seus dados para começar.</p><form id="signup-form" data-form="signup" novalidate><div class="error" id="form-error" role="alert"></div>${field('Nome completo','name',input('name','Digite seu nome'))}${field('E-mail','email',input('email','Digite seu e-mail','email'))}${field('Criar senha','password',`<div class="password-box">${input('password','Crie uma senha','password')}<button class="icon-button" type="button" data-action="reveal" data-target="password" aria-label="Mostrar senha" aria-pressed="false">${icon('eye')}</button></div>`)}${field('Repita a senha','confirm-password',`<div class="password-box">${input('confirm-password','Digite sua senha novamente','password')}<button class="icon-button" type="button" data-action="reveal" data-target="confirm-password" aria-label="Mostrar confirmação da senha" aria-pressed="false">${icon('eye')}</button></div>`)}<button class="btn btn-primary" type="submit" data-od-id="submit-signup">Criar conta ${icon('arrow')}</button></form><p class="signup-footer">Já tem uma conta? <a class="link" href="teapts-login.html">Fazer login</a></p><p class="signup-footer">Protótipo interativo · nenhum dado é enviado ao servidor</p></section></main>${dialogs()}`}
function patients(ctx,state){let list=state.patients;return heading('Pacientes','Acompanhe os pacientes vinculados a você e acesse seus planos de cuidado.',`Bem-vindo, ${ctx.role==='admin'?'Kaio':'Kaio'}.`,buttonLink(ctx.role==='admin'?`${icon('plus')} Criar perfil de paciente`:`${icon('plus')} Criar proposta de PTS`,ctx.role==='admin'?'createPatient':'createPts',ctx,true))+`<div class="toolbar"><div class="search">${icon('search')}<input class="input" type="search" id="patient-search" data-filter="patients" placeholder="Buscar paciente pelo nome" aria-label="Buscar paciente pelo nome" data-od-id="patient-search"></div><span class="count" id="result-count">${list.length} pacientes</span></div><div class="table-card"><table class="ds-table"><thead><tr><th style="width:46%">Paciente</th><th style="width:31%">Situação do PTS</th><th style="width:23%">Acompanhamento</th></tr></thead><tbody>${list.map(p=>`<tr data-search="${esc(p.name)}" data-od-id="patient-${p.id}"><td><div class="patient-cell">${p.source?avatar(true):initials(p.name)}<div><strong>${esc(p.name)}</strong><small>${p.source?'Paciente da referência':'Perfil criado nesta demonstração'}</small></div></div></td><td data-label="Situação">${badge(state.plans[p.id]?states[state.plans[p.id].status]:'Não informada')}</td><td><a class="link" href="${link('pts',ctx,{patient:p.id})}" data-od-id="open-pts-${p.id}">Visualizar PTS ${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div><div id="search-empty" hidden>${empty('Nenhum paciente encontrado','Tente outro nome ou limpe a busca.','search',action('Limpar busca','clear-search'))}</div><div class="table-foot"><span>Somente pacientes vinculados ao seu acesso.</span><span class="num">01</span></div>${ctx.role==='admin'?`<a class="link" href="${link('createPts',ctx)}">Criar uma proposta de PTS ${icon('arrow')}</a>`:''}`}
function createPatient(ctx,state){const available=accounts.filter(a=>!state.createdPatients.includes(a.id));return heading('Criar perfil de paciente','Associe uma conta existente ao paciente e organize sua rede de suporte.','Administração de pacientes')+`<div class="form-grid"><form class="form-panel" data-form="patient" novalidate><h2>Dados do paciente</h2><p>Contas que já possuem um perfil não aparecem nesta lista.</p><div class="error" id="form-error" role="alert"></div>${field('Conta','account',`<select class="input" id="account" name="account" required data-od-id="account-select">${option('','Selecione a conta')}${available.map(a=>option(a.id,a.name)).join('')}</select>`,'Selecione a conta à qual o perfil de paciente será associado.')}<hr class="rule"><div class="row-between"><div><h2>Contatos de suporte</h2><p class="muted small">Opcional · pessoas que ajudam no cuidado.</p></div></div>${action(`${icon('plus')} Adicionar contato`,'add-contact')}<div id="contacts-list"></div><div class="form-actions"><button class="btn btn-primary" type="submit" data-od-id="submit-patient">Criar perfil de paciente</button>${buttonLink('Cancelar','patients',ctx)}</div></form><aside class="aside-panel"><h2>Uma rede de apoio</h2><p>Você pode adicionar nome, descrição, e-mail e telefone de cada contato.</p><p>Um contato de suporte não é, por si só, um responsável tutelar e não recebe acesso às informações clínicas.</p><hr class="rule"><p>O cadastro do perfil é uma operação administrativa. O acompanhamento clínico depende do vínculo com a equipe.</p></aside></div>`}
function teamSelect(exclude='kaio2-psi'){return `<details class="selection" data-od-id="team-selector"><summary>Selecione os profissionais ${icon('down')}</summary>${professionals.filter(p=>p.id!==exclude).map(p=>`<label class="check-row"><input type="checkbox" name="team" value="${p.id}" data-od-id="select-${p.id}"><span>${p.name}<small>${p.specialty}</small></span></label>`).join('')}</details>`}
function createPts(ctx,state){const candidates=[...state.patients,...accounts.filter(a=>a.id==='priscila'||state.createdPatients.includes(a.id))].filter((p,i,a)=>a.findIndex(x=>x.id===p.id)===i&&!['PLANNING','RUNNING'].includes(state.plans[p.id]?.status));const responsible=ctx.role==='admin'?'kaio2-psi':'kaio-psi';return heading('Criar proposta de PTS','Defina o paciente e a equipe para começar um plano de cuidado compartilhado.','Programa Terapêutico Singular')+`<div class="form-grid"><form class="form-panel" data-form="pts" novalidate><div class="steps"><span class="current"><i>1</i> Elaborar proposta</span><span aria-hidden="true">—</span><span><i>2</i> Aprovação do paciente</span></div><div class="error" id="form-error" role="alert"></div>${field('Seu perfil profissional','professional',input('professional','','text',true,professional(responsible).name+' · '+professional(responsible).specialty).replace(' required',' readonly'),'Você será o profissional responsável por esta proposta.')}${field('Paciente','patient',`<select class="input" id="patient" name="patient" required data-od-id="patient-select">${option('','Selecione o paciente')}${candidates.map(p=>option(p.id,p.name)).join('')}</select>`,'São elegíveis pacientes sem PTS aprovado ativo.')}<div class="field"><label>Equipe multidisciplinar <span class="optional">(opcional)</span></label>${teamSelect(responsible)}<small>O responsável poderá adicionar ou remover profissionais depois.</small></div>${field('Situação social','social',`<textarea class="textarea" id="social" name="social" placeholder="Descreva a situação social do paciente" data-od-id="social-situation"></textarea>`,'A descrição poderá ser atualizada pela equipe autorizada.')}<div class="form-actions"><button class="btn btn-primary" type="submit" data-od-id="submit-pts">Criar proposta</button>${buttonLink('Cancelar','patients',ctx)}</div></form><aside class="aside-panel"><h2>O primeiro passo é conjunto.</h2><p>A proposta será apresentada ao paciente. Após a aprovação, o PTS entra em planejamento.</p><p>Cada paciente pode ter apenas um PTS aprovado ativo. Outras propostas pendentes serão rejeitadas ao escolher uma equipe.</p></aside></div>`}
function patientHome(ctx,state,waiting=false){const plan=state.plans.priscila,u=user(ctx,state);return heading(`Bem-vinda, ${esc(u.name.split(' ')[0])}.`,'Um espaço para acompanhar seu cuidado e as pessoas que fazem parte dele.','Área do paciente')+(waiting&&!state.createdPatients.includes(ctx.patient)?empty('Seu perfil está a caminho.','Sua conta foi criada, mas você ainda não está cadastrada como paciente. Aguarde até que seu perfil seja criado.','clock',buttonLink('Ver meu perfil','profile',ctx)):plan?`<div class="welcome-panel"><div>${badge(states[plan.status])}<h2 style="margin-top:22px">Seu plano de cuidado, em um só lugar.</h2><p>Acompanhe as atividades, conheça sua equipe e consulte os documentos do seu prontuário.</p>${buttonLink('Acessar meu PTS','pts',ctx,true)}</div><div class="welcome-diagram" aria-hidden="true"><span>PTS</span></div></div>`:`<div class="welcome-panel"><div><p class="eyebrow" style="color:var(--muted)">Seu próximo passo</p><h2>Vamos começar seu plano de cuidado?</h2><p>Você ainda não tem um PTS ativo. Confira as propostas e escolha a equipe que vai construir esse caminho com você.</p>${buttonLink('Visualizar propostas de PTS','proposals',ctx,true)}</div><div class="welcome-diagram" aria-hidden="true"><span>PTS</span></div></div>`)}
function proposals(ctx,state){const list=state.proposals.filter(p=>p.patientId==='priscila'&&p.status==='DRAFT'),plan=state.plans.priscila;return heading('Propostas de PTS','Conheça a equipe que vai planejar seu Programa Terapêutico Singular.','Seu cuidado, sua escolha')+notice('<strong>Uma equipe por vez.</strong> Ao aceitar uma proposta, as outras propostas pendentes serão automaticamente rejeitadas.')+(list.length?list.map((p,i)=>{const pro=professional(p.responsible);return `<article class="card proposal-card" data-od-id="proposal-${i}"><div class="person-banner">${avatar()}<div><h2>${pro.name}</h2><p>${pro.specialty} · profissional responsável</p></div>${badge('Aguardando sua decisão')}</div><div class="proposal-meta"><span>Paciente<strong>Priscila Martins</strong></span><span>Equipe multidisciplinar<strong>${p.team.length?`${p.team.length} profissionais convidados`:'Definida com o responsável'}</strong></span></div>${p.team.length?`<div class="chips">${p.team.map(id=>badge(professional(id).name+' · '+professional(id).specialty)).join('')}</div>`:''}<div class="form-actions">${action('Escolher esta equipe','approve-proposal',i===0,`data-id="${p.id}"`)}${action('Rejeitar','reject-proposal',false,`data-id="${p.id}"`)}</div></article>`}).join(''):empty(plan?'Sua equipe já foi escolhida.':'Nenhuma proposta pendente','Novas propostas aparecerão aqui quando forem enviadas por um profissional.','plan',plan?buttonLink('Acessar meu PTS','pts',ctx,true):''))}
function pts(ctx,state){const p=person(ctx.patient,state),plan=state.plans[ctx.patient],isPatient=ctx.role==='patient',activities=state.activities.filter(a=>a.patientId===ctx.patient);if(!plan&&ctx.patient==='priscila')return heading('Meu PTS','Acompanhe o plano construído com a sua equipe.')+empty('Nenhum PTS ativo','Escolha uma proposta para começar o planejamento do seu cuidado.','plan',buttonLink('Ver propostas','proposals',ctx,true));const pro=plan?professional(plan.responsible):null,team=(plan?.team||[]).map(professional),canEdit=!isPatient&&plan&&plan.responsible===(ctx.role==='admin'?'kaio2-psi':'kaio-psi');return heading('Programa Terapêutico Singular','Uma visão compartilhada das atividades, da equipe e dos documentos.','Acompanhamento')+banner(ctx,state)+tabs(ctx,'pts')+`<div class="form-grid"><div><details class="accordion" ${ctx.expand==='activities'?'open':''} data-od-id="activities-accordion"><summary>Atividades <span class="count">${activities.length?activities.length+' registradas':'Nenhuma atividade'}</span></summary><div class="accordion-content">${activities.length?activities.map(a=>`<div class="summary-row" data-od-id="activity-${a.id}"><div><strong>${esc(a.title)}</strong><small>${esc(a.frequency)} · ${professional(a.assignee).name}</small></div><div class="actions">${badge(states[a.status])}${canEdit&&a.status==='SUGGESTED'?action('Aprovar','approve-activity',false,`data-id="${a.id}"`):''}${canEdit&&a.status==='RUNNING'?action('Arquivar','archive-activity',false,`data-id="${a.id}"`):''}</div></div>`).join(''):empty('Nenhuma atividade sugerida','As atividades propostas pela equipe aparecerão aqui.','plan','',true)}${canEdit?action(`${icon('plus')} Sugerir atividade`,'add-activity'):''}</div></details><details class="accordion" data-od-id="team-accordion"><summary>Equipe multidisciplinar</summary><div class="accordion-content"><div class="summary-row"><div class="patient-cell">${pro?avatar():initials('Equipe')}<div><strong>${pro?pro.name:'Equipe não informada'}</strong><small>${pro?pro.specialty:'Nenhum profissional identificado nesta referência.'}</small></div></div>${pro?badge('Responsável pelo PTS'):''}</div>${team.map(t=>`<div class="summary-row"><div><strong>${t.name}</strong><small>${t.specialty}</small></div></div>`).join('')}${canEdit?action('Gerenciar equipe','edit-team'):''}</div></details><div class="card row-between" data-od-id="record-shortcut"><div><h2 style="font-size:24px">Prontuário</h2><p class="small muted">Documentos compartilhados entre os planos do paciente.</p></div><a class="icon-button" href="${link('records',ctx)}" aria-label="Abrir prontuário" data-od-id="open-record">${icon('arrow')}</a></div></div><aside class="aside-panel"><h2>Sobre este plano</h2><dl class="detail-grid" style="grid-template-columns:1fr;gap:22px"><div><dt>Paciente</dt><dd>${esc(p.name)}</dd></div><div><dt>Situação</dt><dd>${plan?states[plan.status]:'Não informada na referência'}</dd></div><div><dt>Profissional responsável</dt><dd>${pro?pro.name:'Não informado'}</dd></div></dl>${!isPatient?`<hr class="rule"><h2 style="margin-top:20px">Situação social</h2><p>${esc(plan?.social||'Nenhuma informação registrada.')}</p>${canEdit?action('Editar situação social','edit-social'):''}`:''}<hr class="rule" style="margin-top:22px"><p>O acesso às informações é definido pelo vínculo com o paciente e o PTS.</p></aside></div>`}
function records(ctx,state){const docs=state.documents.filter(d=>d.patientId===ctx.patient);return heading('Prontuário','Documentos do paciente, organizados e disponíveis para a equipe autorizada.','Documentos do cuidado',buttonLink(`${icon('upload')} Enviar documento`,'upload',ctx,true))+banner(ctx,state)+tabs(ctx,'records')+(docs.length?`<div class="toolbar"><div class="search">${icon('search')}<input class="input" type="search" data-filter="documents" placeholder="Buscar documento pelo título" aria-label="Buscar documento pelo título" data-od-id="document-search"></div><span class="count" id="result-count">${docs.length} documentos</span></div><div class="table-card"><table class="ds-table"><thead><tr><th style="width:44%">Documento</th><th style="width:21%">Adicionado em</th><th style="width:20%">Última alteração</th><th style="width:15%">Arquivo</th></tr></thead><tbody>${docs.map(d=>`<tr data-search="${esc(d.title)}" data-od-id="document-${d.id}"><td><div class="patient-cell">${icon('file')}<div><strong>${esc(d.title)}</strong><small>${d.source?'Documento da referência':esc(d.filename||'Arquivo local')}</small></div></div></td><td data-label="Adicionado em" class="num">${d.created}</td><td data-label="Alterado em" class="num">${d.updated||d.created}</td><td><button class="link" data-action="document" data-id="${d.id}" data-od-id="open-${d.id}">${d.source?'Detalhes':'Baixar'} ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div id="search-empty" hidden>${empty('Nenhum documento encontrado','Experimente buscar por outro título.','search')}</div><p class="small muted" style="margin-top:20px">Os documentos das referências não incluem os arquivos originais. Arquivos enviados nesta demonstração ficam disponíveis neste navegador.</p>`:empty('Nenhum documento encontrado','Os documentos enviados para este paciente aparecerão aqui.','folder'))}
function upload(ctx,state){return heading('Enviar documento','Adicione um arquivo ao prontuário de '+esc(person(ctx.patient,state).name)+'.','Prontuário')+`<div class="form-grid"><form class="form-panel" data-form="upload" novalidate><h2>Informações do documento</h2><p>O documento será vinculado a este paciente.</p><div class="error" id="form-error" role="alert"></div>${field('Título','document-title',input('document-title','Dê um título ao documento'))}${field('Descrição <span class="optional">(opcional)</span>','description','<textarea class="textarea" id="description" name="description" placeholder="Adicione uma descrição ou observação sobre o documento" data-od-id="document-description"></textarea>','Se não preenchida, a descrição não será enviada.')}<div class="field"><label for="document-file">Documento</label><div class="upload-area" id="dropzone">${icon('upload')}<strong>Selecione ou arraste um arquivo</strong><small>PDF, PNG, JPG, DOC ou DOCX</small><input type="file" id="document-file" name="document-file" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" required aria-describedby="file-name" data-od-id="document-file"></div><p class="selected-file" id="file-name" aria-live="polite">Nenhum arquivo selecionado.</p><small>Limite desta demonstração: 10 MB por arquivo.</small></div><div class="form-actions"><button class="btn btn-primary" type="submit" data-od-id="submit-upload">Enviar documento</button>${buttonLink('Cancelar','records',ctx)}</div></form><aside class="aside-panel"><h2>Parte da história do cuidado.</h2><p>Use um título que ajude a identificar o conteúdo do documento.</p><p>O prontuário pertence ao paciente e é compartilhado entre os seus PTS.</p><hr class="rule"><p>Nesta demonstração, o arquivo é salvo apenas no navegador. Não há envio para um servidor.</p></aside></div>`}
function timeline(ctx,state){const events=state.events.filter(e=>e.patientId===ctx.patient).slice().reverse();return heading('Histórico do PTS','Acompanhe os acontecimentos e as mudanças no plano de cuidado.','Linha do tempo')+banner(ctx,state)+tabs(ctx,'timeline')+(events.length?`<ol class="time-list">${events.map((e,i)=>`<li data-od-id="event-${i}"><time>${new Date(e.date).toLocaleString('pt-BR')}</time><div><strong>${esc(e.title)}</strong><p>${esc(e.description)}</p></div></li>`).join('')}</ol>`:empty('A história começa aqui.','Nenhum evento registrado ainda. As ações realizadas neste PTS aparecerão em ordem cronológica.','history'))}
function profile(ctx,state){const u=user(ctx,state);return heading('Meu perfil','Seus dados de identificação e os perfis associados à sua conta.','Minha conta')+`<div class="profile-main"><article class="card profile-card" data-od-id="profile-card"><div class="person-banner">${avatar()}<div><h2>${esc(u.name)}</h2><p>${u.role}</p></div></div><dl class="detail-grid"><div><dt>${ctx.role==='admin'?'Nome da conta':'Nome completo'}</dt><dd>${esc(u.name)}</dd></div><div><dt>${ctx.role==='admin'?'Tipo de acesso':'E-mail'}</dt><dd>${ctx.role==='admin'?u.role:esc(u.email||'Não informado')}</dd></div></dl>${u.specialties.length?`<p class="small muted">Perfis e especialidades</p><div class="chips">${u.specialties.map(badge).join('')}</div>`:''}<div class="form-actions">${ctx.role!=='admin'?action(`${icon('lock')} Redefinir senha`,'reset-password',true):''}${action(`${icon('logout')} Sair da conta`,'logout',ctx.role==='admin')}</div></article><p class="small muted" style="margin-top:20px">As permissões de acesso dependem dos perfis e dos vínculos autorizados para a sua conta.</p></div>`}
function render(screen,ctx,state){if(screen==='overview')return overview();if(screen==='signup')return signup();const renderers={patients,createPatient,createPts,patientHome,proposals,pts,records,upload,timeline,profile,waiting:(c,s)=>patientHome(c,s,true)};return shell(screen,ctx,state,renderers[screen](ctx,state))}
function defaultContext(screen,query=''){const q=new URLSearchParams(query),patientScreens=['patientHome','waiting','proposals'];return {role:q.get('role')|| (patientScreens.includes(screen)?'patient':screen==='createPatient'?'admin':'professional'),patient:q.get('patient')||((q.get('role')==='patient'||patientScreens.includes(screen))?'priscila':'maria'),expand:q.get('expand')||'',scenario:q.get('scenario')||''}}
function approve(state,id){const p=state.proposals.find(p=>p.id===id);if(!p||p.status!=='DRAFT'||['PLANNING','RUNNING'].includes(state.plans[p.patientId]?.status))throw Error('Esta proposta não está disponível para aprovação.');state.proposals.filter(x=>x.patientId===p.patientId&&x.status==='DRAFT').forEach(x=>x.status=x.id===id?'PLANNING':'REJECTED');state.plans[p.patientId]={...p,status:'PLANNING',team:[...p.team]};return p}
function addPatient(state,id,contacts){const account=accounts.find(a=>a.id===id);if(!account||state.createdPatients.includes(id))throw Error('Selecione uma conta sem perfil de paciente.');state.createdPatients.push(id);if(!state.patients.some(p=>p.id===id))state.patients.push({...account,source:false});state.contacts[id]=contacts;return account}
function addProposal(state,patientId,responsible,team,social){if(!patientId)throw Error('Selecione um paciente.');if(['PLANNING','RUNNING'].includes(state.plans[patientId]?.status))throw Error('Este paciente já possui um PTS ativo.');const p={id:'proposta-'+Date.now(),patientId,responsible,team:team.filter(id=>id!==responsible),social,status:'DRAFT'};state.proposals.push(p);return p}
function boot(){const screen=document.body.dataset.screen,ctx=defaultContext(screen,location.search),key='teapts-demo-v3';let state=initial(),draftContacts=[];try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.version===3)state=saved}catch{}if(ctx.scenario==='approved'&&!state.plans.priscila){const p=state.proposals.find(p=>p.patientId==='priscila'&&p.status==='DRAFT');if(p)approve(state,p.id)}

const sidebarMedia=window.matchMedia('(max-width: 920px)');let sidebarCollapsed=false,sidebarOpen=false;
try{sidebarCollapsed=localStorage.getItem('teapts-sidebar-collapsed')==='true'}catch{}
function syncSidebar(){const app=document.querySelector('.app'),sidebar=document.getElementById('sidebar'),toggle=document.querySelector('[data-action="sidebar-toggle"]');if(!app||!sidebar||!toggle)return;const mobile=sidebarMedia.matches,expanded=mobile?sidebarOpen:!sidebarCollapsed;app.classList.toggle('sidebar-collapsed',!mobile&&sidebarCollapsed);sidebar.classList.toggle('open',mobile&&sidebarOpen);toggle.setAttribute('aria-expanded',String(expanded));const label=mobile?(expanded?'Fechar navegação':'Abrir navegação'):(expanded?'Recolher barra lateral':'Expandir barra lateral');toggle.setAttribute('aria-label',label);toggle.setAttribute('title',label)}
sidebarMedia.addEventListener('change',()=>{sidebarOpen=false;syncSidebar()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sidebarMedia.matches&&sidebarOpen){sidebarOpen=false;syncSidebar();document.querySelector('[data-action="sidebar-toggle"]')?.focus()}});

function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('O navegador não permitiu salvar o estado desta demonstração.')}}
function event(title,description,patient=ctx.patient){state.events.push({title,description,patientId:patient,date:new Date().toISOString()})}
function draw(){document.getElementById('app-root').innerHTML=render(screen,ctx,state);const m=document.getElementById('modal');if(m)m.addEventListener('click',e=>{if(e.target===m){const r=m.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)m.close()}});if(screen==='createPatient')contactsDraw();wireDrop();syncSidebar()}
function go(target,extra={}){save();location.href=link(target,ctx,extra)}
function toast(message){const t=document.getElementById('toast');if(t){t.textContent=message;setTimeout(()=>{if(t.isConnected)t.textContent=''},5000)}}
function modal(html){document.getElementById('modal-body').innerHTML=html;document.getElementById('modal').showModal()}
function close(){document.getElementById('modal')?.close()}
function error(form,message){let el=form.querySelector('.error');if(!el){el=document.createElement('p');el.className='error';el.setAttribute('role','alert');form.prepend(el)}el.textContent=message}
function validate(form){const required=[...form.querySelectorAll('[required]')];for(const e of required){e.removeAttribute('aria-invalid');if(!String(e.value).trim()||!e.checkValidity()){e.setAttribute('aria-invalid','true');error(form,e.type==='email'?'Informe um e-mail válido.':'Preencha os campos obrigatórios antes de continuar.');e.focus();return false}}form.querySelector('.error').textContent='';return true}
function contactsDraw(){const el=document.getElementById('contacts-list');if(el)el.innerHTML=draftContacts.map((c,i)=>`<article class="contact-row" data-od-id="contact-${i}"><div><strong>${esc(c.name)}</strong><p>${esc(c.description||'Contato de suporte')}</p><p>${esc([c.email,c.phone].filter(Boolean).join(' · '))}</p></div><button type="button" class="icon-button" data-action="remove-contact" data-index="${i}" aria-label="Remover contato ${esc(c.name)}">${icon('trash')}</button></article>`).join('')}
function profileModal(){const u=user(ctx,state);modal(`<div class="profile-popover">${avatar()}<h2 id="modal-title">${esc(u.name)}</h2><p>Meu perfil · ${u.role}</p><div class="chips">${u.specialties.map(badge).join('')}</div><div class="form-actions">${buttonLink('Ver perfil completo','profile',ctx)}${action('Sair da conta','logout',true)}</div></div>`)}
function confirmation(title,desc,label,act,id=''){modal(`<h2 id="modal-title">${title}</h2><p>${desc}</p><div class="form-actions">${action('Cancelar','close')}${action(label,act,true,`data-id="${esc(id)}"`)}</div>`)}
async function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('teapts-demo-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function filePut(id,file){const store=await db();return new Promise((resolve,reject)=>{const t=store.transaction('files','readwrite');t.objectStore('files').put(file,id);t.oncomplete=()=>{store.close();resolve()};t.onerror=()=>{store.close();reject(t.error)}})}
async function fileGet(id){const store=await db();return new Promise((resolve,reject)=>{const t=store.transaction('files','readonly'),r=t.objectStore('files').get(id);r.onsuccess=()=>{store.close();resolve(r.result)};r.onerror=()=>{store.close();reject(r.error)}})}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{
if(a==='sidebar-toggle'){if(sidebarMedia.matches){sidebarOpen=!sidebarOpen}else{sidebarCollapsed=!sidebarCollapsed;try{localStorage.setItem('teapts-sidebar-collapsed',String(sidebarCollapsed))}catch{}}syncSidebar()}
if(a==='menu-close'){sidebarOpen=false;syncSidebar();document.querySelector('[data-action="sidebar-toggle"]')?.focus()}
if(a==='close')close();if(a==='profile')profileModal();if(a==='logout')confirmation('Sair da conta?','Você voltará à tela de login. Nenhuma sessão real está ativa nesta demonstração.','Sair','confirm-logout');if(a==='confirm-logout'){location.href='teapts-login.html'}
if(a==='reveal'){const el=document.getElementById(b.dataset.target),show=el.type==='password';el.type=show?'text':'password';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha')}
if(a==='clear-search'){const s=document.getElementById('patient-search');s.value='';s.dispatchEvent(new Event('input',{bubbles:true}));s.focus()}
if(a==='add-contact')modal(`<h2 id="modal-title">Adicionar contato de suporte</h2><p>Inclua uma pessoa que participa da rede de apoio.</p><form data-form="contact" novalidate><div class="error" role="alert"></div>${field('Nome do contato','contact-name',input('contact-name','Nome completo'))}${field('Descrição <span class="optional">(opcional)</span>','contact-description',input('contact-description','Relação com o paciente','text',false))}${field('E-mail <span class="optional">(opcional)</span>','contact-email',input('contact-email','email@exemplo.com','email',false))}${field('Telefone <span class="optional">(opcional)</span>','contact-phone',input('contact-phone','(00) 00000-0000','tel',false))}<div class="form-actions">${action('Cancelar','close')}<button class="btn btn-primary" type="submit" data-od-id="save-contact">Adicionar contato</button></div></form>`);
if(a==='remove-contact'){draftContacts.splice(Number(b.dataset.index),1);contactsDraw()}
if(a==='approve-proposal')confirmation('Aceitar proposta?','Ao aceitar esta equipe, todas as outras propostas pendentes serão automaticamente rejeitadas. Seu PTS entrará em planejamento.','Aceitar proposta','confirm-approve',id);
if(a==='confirm-approve'){const p=approve(state,id);event('Proposta aprovada','A equipe foi escolhida e o PTS entrou em planejamento.',p.patientId);go('pts',{patient:p.patientId,role:'patient'})}
if(a==='reject-proposal')confirmation('Rejeitar proposta?','Esta equipe não iniciará o planejamento do seu PTS. Você poderá analisar outras propostas disponíveis.','Rejeitar proposta','confirm-reject',id);
if(a==='confirm-reject'){const p=state.proposals.find(p=>p.id===id);if(p?.status==='DRAFT'){p.status='REJECTED';event('Proposta rejeitada','O paciente rejeitou a proposta de '+professional(p.responsible).name+'.',p.patientId);save();draw();toast('Proposta rejeitada.')}}

if(a==='reset-password')modal(`<h2 id="modal-title">Redefinir senha</h2><p>Escolha uma nova senha para sua conta.</p><form data-form="reset-password" novalidate><div class="error" role="alert"></div>${field('Nova senha','reset-password',input('reset-password','Digite a nova senha','password').replace(' required',' autocomplete="new-password" required'))}${field('Confirmar nova senha','reset-confirm',input('reset-confirm','Repita a nova senha','password').replace(' required',' autocomplete="new-password" required'))}<p class="small muted">Demonstração: nenhuma senha real será alterada.</p><div class="form-actions">${action('Cancelar','close')}<button class="btn btn-primary" type="submit" data-od-id="confirm-reset-password">Redefinir senha</button></div></form>`);
if(a==='edit-social'){modal(`<h2 id="modal-title">Situação social</h2><form data-form="social"><div class="error" role="alert"></div>${field('Descrição','social-edit',`<textarea class="textarea" id="social-edit" name="social-edit">${esc(state.plans[ctx.patient]?.social||'')}</textarea>`)}<div class="form-actions">${action('Cancelar','close')}<button class="btn btn-primary" data-od-id="save-social">Salvar alteração</button></div></form>`)}
if(a==='edit-team')modal(`<h2 id="modal-title">Equipe multidisciplinar</h2><p>Selecione os profissionais que participarão do plano.</p><form data-form="team"><div class="error" role="alert"></div>${professionals.filter(p=>p.id!==state.plans[ctx.patient].responsible).map(p=>`<label class="check-row"><input type="checkbox" name="team" value="${p.id}" ${state.plans[ctx.patient].team.includes(p.id)?'checked':''}><span>${p.name}<small>${p.specialty}</small></span></label>`).join('')}<div class="form-actions">${action('Cancelar','close')}<button class="btn btn-primary" data-od-id="save-team">Salvar equipe</button></div></form>`);
if(a==='add-activity')modal(`<h2 id="modal-title">Sugerir atividade</h2><form data-form="activity" novalidate><div class="error" role="alert"></div>${field('Título da atividade','activity-title',input('activity-title','Descreva a atividade'))}${field('Frequência','frequency',`<select class="input" id="frequency" required>${option('','Selecione a frequência')}${['Diária','Semanal','Quinzenal','Mensal','Única'].map(t=>option(t,t)).join('')}</select>`)}${field('Profissional responsável','assignee',`<select class="input" id="assignee" required>${[state.plans[ctx.patient].responsible,...state.plans[ctx.patient].team].map(id=>option(id,professional(id).name+' · '+professional(id).specialty)).join('')}</select>`)}<div class="form-actions">${action('Cancelar','close')}<button class="btn btn-primary" data-od-id="save-activity">Sugerir atividade</button></div></form>`);
if(a==='approve-activity'||a==='archive-activity'){const item=state.activities.find(x=>x.id===id);if(item&&ctx.role!=='patient'&&((a==='approve-activity'&&item.status==='SUGGESTED')||(a==='archive-activity'&&item.status==='RUNNING'))){item.status=a==='approve-activity'?'RUNNING':'ARCHIVED';event('Atividade '+(a==='approve-activity'?'aprovada':'arquivada'),item.title);save();ctx.expand='activities';draw();toast('Atividade atualizada.')}}
if(a==='document'){const d=state.documents.find(x=>x.id===id);if(d.source)modal(`<h2 id="modal-title">${esc(d.title)}</h2><p>Adicionado em ${d.created}. Última alteração em ${d.updated}.</p><p>Os metadados estão na imagem de referência, mas o arquivo original não foi fornecido. Não há um documento disponível para baixar.</p><div class="form-actions">${action('Entendi','close')}</div>`);else{const file=await fileGet(id);if(!file){modal('<h2 id="modal-title">Arquivo indisponível</h2><p>Este arquivo não está mais armazenado no navegador. Envie o documento novamente para acessá-lo.</p>');return}const url=URL.createObjectURL(file),el=document.createElement('a');el.href=url;el.download=d.filename;document.body.appendChild(el);el.click();el.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.matches('[data-filter]')){const query=e.target.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();let count=0;document.querySelectorAll('tr[data-search]').forEach(row=>{const match=row.dataset.search.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query);row.hidden=!match;if(match)count++});document.querySelector('.table-card').hidden=!count;document.getElementById('search-empty').hidden=!!count;document.getElementById('result-count').textContent=count+' '+(e.target.dataset.filter==='patients'?'pacientes':'documentos')}else if(e.target.matches('input,textarea,select'))e.target.removeAttribute('aria-invalid')});
function selectedFile(file){document.getElementById('file-name').textContent=file?file.name+' · '+(file.size/1024/1024).toFixed(2).replace('.',',')+' MB':'Nenhum arquivo selecionado.'}
function wireDrop(){const zone=document.getElementById('dropzone');if(!zone)return;const input=document.getElementById('document-file');input.addEventListener('change',()=>selectedFile(input.files[0]));zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging')});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');if(e.dataTransfer.files.length){input.files=e.dataTransfer.files;selectedFile(input.files[0])}})}
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();if(!validate(f))return;const value=id=>f.querySelector('#'+id)?.value.trim()||'',kind=f.dataset.form;try{
if(kind==='signup'){if(value('password')!==value('confirm-password')){error(f,'As senhas não coincidem. Digite a mesma senha nos dois campos.');f.querySelector('#confirm-password').setAttribute('aria-invalid','true');f.querySelector('#confirm-password').focus();return}state.newAccount={name:value('name'),email:value('email')};f.querySelector('#password').value='';f.querySelector('#confirm-password').value='';go('waiting',{role:'patient',patient:'new-account'})}

if(kind==='reset-password'){if(value('reset-password')!==value('reset-confirm')){error(f,'As senhas não coincidem. Digite a mesma senha nos dois campos.');f.querySelector('#reset-confirm').setAttribute('aria-invalid','true');f.querySelector('#reset-confirm').focus();return}f.querySelector('#reset-password').value='';f.querySelector('#reset-confirm').value='';modal(`<h2 id="modal-title">Redefinição simulada</h2><p>A confirmação da nova senha foi validada. Nenhuma senha real foi alterada neste protótipo.</p><div class="form-actions">${action('Voltar ao perfil','close',true)}</div>`)}
if(kind==='contact'){const em=f.querySelector('#contact-email');if(em.value&&!em.checkValidity()){error(f,'Informe um e-mail válido para o contato.');em.focus();return}draftContacts.push({name:value('contact-name'),description:value('contact-description'),email:value('contact-email'),phone:value('contact-phone')});close();contactsDraw()}
if(kind==='patient'){if(ctx.role!=='admin')throw Error('Este cadastro requer o perfil administrativo.');addPatient(state,value('account'),draftContacts);event('Perfil de paciente criado','Perfil e contatos de suporte registrados nesta demonstração.',value('account'));save();go('patients',{notice:'patient-created'})}
if(kind==='pts'){const selected=[...f.querySelectorAll('[name=team]:checked')].map(x=>x.value),p=addProposal(state,value('patient'),ctx.role==='admin'?'kaio2-psi':'kaio-psi',selected,value('social'));event('Proposta de PTS criada','A proposta aguarda a decisão do paciente.',p.patientId);save();modal(`<h2 id="modal-title">Proposta criada</h2><p>A proposta de ${esc(person(p.patientId,state).name)} está aguardando aprovação. O planejamento começa após a escolha da equipe.</p><div class="form-actions">${buttonLink('Voltar aos pacientes','patients',ctx)}</div>`);f.reset()}
if(kind==='social'){if(ctx.role==='patient'||!state.plans[ctx.patient])throw Error('A edição exige um profissional da equipe.');state.plans[ctx.patient].social=value('social-edit');event('Situação social atualizada','A equipe atualizou o contexto social do paciente.');save();draw();toast('Situação social atualizada.')}
if(kind==='team'){if(ctx.role==='patient')throw Error('A edição exige o responsável pelo PTS.');state.plans[ctx.patient].team=[...f.querySelectorAll('[name=team]:checked')].map(x=>x.value);event('Equipe atualizada','A composição da equipe multidisciplinar foi atualizada.');save();draw();toast('Equipe atualizada.')}
if(kind==='activity'){state.activities.push({id:'atv-'+Date.now(),patientId:ctx.patient,title:value('activity-title'),frequency:value('frequency'),assignee:value('assignee'),status:'SUGGESTED'});event('Atividade sugerida',value('activity-title'));save();ctx.expand='activities';draw();toast('Atividade sugerida para este PTS.')}
if(kind==='upload'){const file=document.getElementById('document-file').files[0];if(!file||!/\.(pdf|png|jpe?g|docx?)$/i.test(file.name))throw Error('Selecione um arquivo PDF, PNG, JPG, DOC ou DOCX.');if(file.size>10*1024*1024)throw Error('O arquivo deve ter no máximo 10 MB nesta demonstração.');const btn=f.querySelector('[type=submit]');btn.disabled=true;btn.textContent='Salvando documento…';try{const id='doc-'+Date.now();await filePut(id,file);state.documents.push({id,patientId:ctx.patient,title:value('document-title'),description:value('description'),filename:file.name,created:new Date().toLocaleDateString('pt-BR'),source:false});event('Documento adicionado',value('document-title'));save();go('records',{notice:'document-added'})}finally{btn.disabled=false;btn.textContent='Enviar documento'}}
}catch(err){error(f,err.message||'Não foi possível concluir. Tente novamente.')}});
save();draw();const n=new URLSearchParams(location.search).get('notice');if(n==='patient-created')toast('Perfil de paciente criado com sucesso.');if(n==='document-added')toast('Documento adicionado ao prontuário.');
}
const api={paths,titles,initial,render,defaultContext,professionals,accounts,approve,addPatient,addProposal,boot};if(typeof module!=='undefined')module.exports=api;else{root.TEAPTS=api;boot()}
})(typeof window!=='undefined'?window:globalThis);
